parameters.jsCode:
// Deterministic checks. The agent's output is a proposal; nothing here trusts it
// without comparing against config or a fresh read of the system of record.
const cfg = $('Config').first().json;
// n8n links each item back to the request it came from. That link can break after the AI
// Agent node (seen live), so fall back to the node's output when it holds exactly one item,
// which cannot be ambiguous.
const one = (name) => { try { return $(name).item.json; } catch (e) { const all = $(name).all(); if (all.length === 1) return all[0].json; throw e; } };
let out = null;
try { out = one('Site incident agent').output ?? null; } catch (e) {} // unreadable output is treated as none

const reasons = [];
if (!out) reasons.push('agent_produced_no_valid_output');
if (out && !(typeof out.confidence === 'number' && out.confidence >= cfg.min_confidence)) {
  reasons.push('confidence ' + out?.confidence + ' below ' + cfg.min_confidence);
}

const req = one('Normalize incident'); // one(): defined by guardPreamble; survives a lost item link
const ev = $json; // fresh read: { incident, camera_events, logs } for the site and day of the incident
const inc = ev.incident ?? {};
const cams = new Map((ev.camera_events ?? []).map((e) => [e.event_id, e]));
const logs = new Map((ev.logs ?? []).map((l) => [l.log_id, l]));
// The incident record is the source of truth for the window.
const start = Date.parse(inc.window_start ?? req.window_start);
const end = Date.parse(inc.window_end ?? req.window_end);
const hasAny = (text, terms) => { const t = String(text ?? '').toLowerCase(); return terms.filter((k) => t.includes(String(k).toLowerCase())); };

if (!inc.incident_id) reasons.push('incident ' + req.incident_id + ' not found on re-read');
if (inc.status && !['open', 'reported', 'under_review'].includes(inc.status)) reasons.push('incident status is now ' + inc.status);
if (inc.report_filed) reasons.push('a report is already filed for this incident');

// Every cited record must exist in the fresh read, carry the same time, and sit inside the window.
const timeline = [];
const camIds = [];
const logIds = [];
const cited = out?.timeline ?? [];
if (out && !cited.length) reasons.push('pack has no timeline entries');
for (const e of cited) {
  const rec = e.source === 'camera_event' ? cams.get(e.ref_id) : e.source === 'site_log' ? logs.get(e.ref_id) : null;
  if (!rec) { reasons.push(e.source + ' ' + e.ref_id + ' was not returned by the system of record'); continue; }
  const recAt = e.source === 'camera_event' ? rec.occurred_at : rec.logged_at;
  const ts = Date.parse(recAt);
  if (!(ts >= start && ts <= end)) reasons.push(e.source + ' ' + e.ref_id + ' at ' + recAt + ' is outside the incident window');
  if (Math.abs(Date.parse(e.at) - ts) > 60000) reasons.push(e.source + ' ' + e.ref_id + ' cited at ' + e.at + ' but recorded at ' + recAt);
  (e.source === 'camera_event' ? camIds : logIds).push(e.ref_id);
  timeline.push({ at: new Date(ts).toISOString(), source: e.source, ref_id: e.ref_id, what_happened: e.what_happened });
}
timeline.sort((a, b) => Date.parse(a.at) - Date.parse(b.at));

// Injuries and serious near misses go to the safety manager, whatever the agent concluded.
const citedLogText = logIds.map((id) => logs.get(id)?.text ?? '').join(' ');
const injuryWords = hasAny(req.report_note + ' ' + citedLogText, cfg.injury_terms ?? []);
const seriousTypes = [inc.incident_type, req.incident_type, ...camIds.map((id) => cams.get(id)?.event_type)].filter((t) => (cfg.serious_potential_types ?? []).includes(t));
const injury = !!inc.injury_reported || !!out?.injury_involved || out?.classification === 'injury' || injuryWords.length > 0;
const serious = !!out?.serious_potential || seriousTypes.length > 0;
if (injury) reasons.push('possible injury (' + [inc.injury_reported ? 'injury reported on the incident' : null, out?.injury_involved ? 'agent found an injury' : null, injuryWords.length ? 'words: ' + injuryWords.join(', ') : null].filter(Boolean).join('; ') + '): the safety manager handles this incident and decides OSHA recordability');
else if (serious) reasons.push('near miss with serious potential (' + ([...new Set(seriousTypes)].join(', ') || 'agent assessment') + '): the safety manager reviews it before anything is filed');

const action = {
  type: 'file_incident_report',
  incident_id: req.incident_id,
  project_id: req.project_id,
  site_id: req.site_id,
  window_start: new Date(start).toISOString(),
  window_end: new Date(end).toISOString(),
  classification: out?.classification ?? null,
  injury_involved: injury,
  serious_potential: serious,
  summary: out?.summary ?? '',
  timeline,
  contributing_factors: out?.contributing_factors ?? [],
  corrective_actions: out?.corrective_actions ?? [],
  evidence_gaps: out?.evidence_gaps ?? [],
  evidence: { camera_event_ids: [...new Set(camIds)], log_ids: [...new Set(logIds)] },
};
const summary = 'Incident ' + req.incident_id + ' · project ' + req.project_id + ' · ' + action.window_start + ' to ' + action.window_end + '\n'
  + 'Classification: *' + action.classification + '* · ' + action.evidence.camera_event_ids.length + ' camera events, ' + action.evidence.log_ids.length + ' logs cited'
  + (action.evidence_gaps.length ? ' · ' + action.evidence_gaps.length + ' evidence gaps' : '') + '\n'
  + action.summary + '\n'
  + 'Corrective actions: ' + (action.corrective_actions.join('; ') || 'none proposed');
const ok = reasons.length === 0;
const isNoop = typeof noop !== 'undefined' && noop === true;
const route = !ok ? 'escalate' : isNoop ? 'none' : 'approve';
return { json: { business_key: req.business_key, route, guardrail_reasons: reasons, action, approval_summary: summary, planned_actions: ok && !isNoop ? [action] : [] } };

// The approval request goes to one named person, so the approver is that person.
// Slack returns { data: { approved, respondedAt } }; a timeout resumes without it.
const cfg = $('Config').first().json;
const approved = $json.data?.approved;
return {
  json: {
    decision: approved === true ? 'approved' : approved === false ? 'declined' : 'timed_out',
    approver: cfg.approver_slack_user,
    decided_at: $json.data?.respondedAt ?? new Date().toISOString(),
    handoff_reason: approved === true || approved === false ? '' : 'approval timed out after ' + cfg.approval_timeout_hours + ' hours',
  },
};

// Done only when the system of record shows what was planned.
// Read the plan even if n8n lost the item link (seen live after the AI Agent node).
const one = (name) => { try { return $(name).item.json; } catch (e) { const all = $(name).all(); if (all.length === 1) return all[0].json; throw e; } };
const planned = one('Guardrails').action;
const r = $json.report ?? {};
const same = (a, b) => JSON.stringify([...(a ?? [])].sort()) === JSON.stringify([...(b ?? [])].sort());
const ok = $json.status === 'report_filed'
  && same(r.camera_event_ids, planned.evidence.camera_event_ids)
  && same(r.log_ids, planned.evidence.log_ids);
const detail = 'incident shows ' + $json.status + ' with ' + (r.camera_event_ids ?? []).length + ' camera events and ' + (r.log_ids ?? []).length + ' logs, expected report_filed with ' + planned.evidence.camera_event_ids.length + ' and ' + planned.evidence.log_ids.length;
return { json: { verified: ok, verify_failed: !ok, verify_detail: ok ? '' : detail } };

// Collects everything a reviewer needs in one record: the request, what the agent
// proposed, why the guardrails stopped it, and the tool calls behind it.
// Every lookup is guarded: this node is the safety net, so it must never be the step that fails.
// n8n links each item back to the request it came from. That link can break after the AI
// Agent node (seen live), so fall back to the node's output when it holds exactly one item,
// which cannot be ambiguous.
const one = (name) => { try { return $(name).item.json; } catch (e) { const all = $(name).all(); if (all.length === 1) return all[0].json; throw e; } };
let intake = null;
let agent = null;
let guard = null;
try { intake = one('Normalize incident'); } catch (e) {}
try { agent = one('Site incident agent'); } catch (e) {}
try { guard = one('Guardrails'); } catch (e) {}

const reasons = [...(guard?.guardrail_reasons ?? [])];
if (!intake) {
  // n8n could not link this item back to its request. Keep whatever identifies it and say so.
  intake = { business_key: $json.business_key ?? null };
  reasons.push('item_context_lost: the request could not be linked to this failure; check the n8n execution');
}
if ($json.error) reasons.push('system_error: ' + ($json.error.message ?? JSON.stringify($json.error)).slice(0, 300));
if ($json.verify_failed) reasons.push('verification_failed: ' + $json.verify_detail);
if ($json.handoff_reason) reasons.push($json.handoff_reason);
if (!agent?.output && !reasons.length) reasons.push('agent_produced_no_valid_output');
if (!reasons.length) {
  const o = agent.output;
  reasons.push('agent recommends review: ' + (o.decision ?? o.recommended_action ?? o.classification ?? o.route_to_queue ?? 'see proposal'));
}

const REDACT = [].map((p) => new RegExp(p, 'g'));
const scrub = (text) => REDACT.reduce((t, r) => t.replace(r, '[redacted]'), String(text ?? ''));
// The masks also apply to what the model wrote, in case it repeated a number it read.
const scrubJson = (v) => {
  if (!REDACT.length || v == null) return v;
  try { return JSON.parse(scrub(JSON.stringify(v))); } catch (e) { return scrub(JSON.stringify(v)); }
};
const trace = (agent?.intermediateSteps ?? []).map((s) => ({
  tool: s.action?.tool,
  input: s.action?.toolInput,
  observation: scrub(s.observation).slice(0, 1500),
}));

const summary = 'Incident ' + intake.incident_id + ' · project ' + intake.project_id + ' · ' + intake.incident_type + (guard?.action?.injury_involved ? ' · POSSIBLE INJURY, safety manager' : guard?.action?.serious_potential ? ' · serious potential, safety manager' : '');
// Slack-safe copies: request, document and model text can contain Slack markup such as <!channel>.
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
return {
  json: {
    business_key: intake.business_key,
    team: "site safety",
    reasons,
    proposed: scrubJson(agent?.output ?? null),
    confidence: agent?.output?.confidence ?? null,
    questions: scrubJson(agent?.output?.questions_for_human ?? []),
    trace,
    summary,
    slack: { key: esc(intake.business_key), summary: esc(summary), reasons: esc(reasons.join('; ')) },
  },
};

parameters.query:
INSERT INTO agent_exceptions (workflow, business_key, team, reasons, proposed_action, confidence, questions, trace, summary, n8n_execution_id)
VALUES ($1, $2, $3, $4::jsonb, $5::jsonb, $6, $7::jsonb, $8::jsonb, $9, $10)
RETURNING id;

